INSERT INTO prompt_templates(id,title,category,prompt,published) VALUES
('product-white-background','电商白底主图','商品','为一只白色陶瓷马克杯制作电商主图；如有参考图，以参考商品为准，保持外形、比例、材质、颜色和标识一致。商品完整居中，使用接近纯白的背景、柔和棚拍光与自然接触阴影，突出杯口和把手的真实细节。画面简洁，不添加道具、促销文字、水印或未经证实的功能。',true),
('product-lifestyle','商品生活方式图','商品','拍摄一款护手霜的生活方式广告；若提供参考商品，忠实保留其包装、标签和颜色。将商品置于晨光中的浅色梳妆台，搭配少量棉布与一枝绿植，营造干净、温暖的日常使用氛围。商品是视觉焦点，背景适度虚化，道具不遮挡主体。不得新增品牌、功效承诺或无关文字。',true),
('product-material-detail','材质细节特写','商品','为一只皮革手提包制作材质细节图；有参考图时沿用原商品。采用近距离商业摄影，突出皮革纹理、车线与金属配件，柔和侧光展示表面起伏，局部清晰、背景自然虚化。维持真实结构与工艺，不凭空新增口袋、配件或标识，不添加文字和水印。',true),
('campaign-seasonal','春日活动海报','宣传','制作一张春日市集活动的竖版海报，以浅绿色、奶油白和少量暖黄色构成清新配色。主体为花束、果蔬与帆布摊位组成的简洁场景，构图有前后层次，上方预留标题位置，下方留出时间地点信息区。只呈现画面与留白，不自行编造活动日期、地址、商家名称或文字。',true),
('campaign-new-product','新品发布视觉','宣传','设计一张便携蓝牙音箱的新品发布主视觉；如有参考商品，以参考为准。采用深蓝背景、克制的轮廓光与简洁几何台座，突出产品完整造型，营造精密而可信的科技感。主体偏右，左侧保留清晰的标题与卖点排版空间。不添加虚构参数、认证标记、品牌或随机文字。',true),
('campaign-editorial-cover','专题封面构图','宣传','为一篇关于城市慢生活的专题文章设计横版封面。画面呈现安静街角、街边咖啡桌与树影，使用米白、砖红和深绿的协调配色，带有克制的编辑摄影气质。主体集中在中下部，上方留出干净标题区，缩小后仍能辨认主题。不生成标题文字、报刊标识或水印。',true),
('photo-food','美食自然光摄影','摄影','拍摄一碗刚出锅的番茄意大利面，置于靠窗的木桌上，搭配少量罗勒叶与一把餐叉。以自然侧光突出酱汁、面条和食材的真实质感，轻微蒸汽增添温度，背景柔和虚化。采用适合菜单展示的俯斜视角，摆盘精致但不过度装饰，避免夸张饱和度和无关文字。',true),
('photo-travel','旅行纪实风景','摄影','创作一张清晨山间湖泊的旅行摄影。远山有层次，薄雾贴近水面，岸边松树形成前景，柔和日光照亮湖面的一小片区域。采用自然色彩与真实空间透视，保留水面细微波纹，画面安静、通透，不出现不合理的巨大月亮、重复树木、文字或水印。',true),
('photo-still-life','静物杂志摄影','摄影','拍摄一组适合生活方式杂志的静物：透明玻璃水杯、一本合上的素色书与一枝白花，摆放在米色桌面。采用单侧窗光，保留玻璃的透明度、合理折射和柔和阴影，物件疏密有序，色彩克制。画面以质感与留白为主，不出现可辨识的书名、品牌和额外文字。',true),
('photo-architecture','建筑外观摄影','摄影','拍摄一座位于街角的现代小型美术馆，白色墙面与大面积玻璃立面，周围有少量行道树和步行空间。采用傍晚柔和自然光，突出建筑体块、材料与入口关系。保持竖线基本垂直、尺度可信，玻璃反射与环境一致。不添加虚构招牌、文字或不合理的重复构件。',true),
('illustration-picture-book','温暖绘本插画','插画','绘制一幅儿童绘本插画：一只小狐狸在雨后的森林里，把捡到的橡果交给松鼠。采用柔和水粉质感、温暖低饱和配色和清晰轮廓，角色表情友善，动作易于理解。用前景叶片、中景角色与远景树林形成层次，保留少量纸张纹理，不添加对话框、文字或水印。',true),
('illustration-isometric','等距微缩场景','插画','绘制一间独立书店的等距微缩插画，展示书架、阅读桌、收银台与临街橱窗。采用统一的等距视角、简洁几何形体和暖木色配色，物件比例协调，动线清晰，有少量绿植和阅读中的人物作为点缀。背景保持干净，不出现随机文字、扭曲透视或拥挤细节。',true),
('illustration-flat','扁平主题插画','插画','为远程协作主题创作一幅扁平插画：几位成年人通过桌面设备共同讨论一个项目。采用清晰的大色块、圆润几何形状和蓝橙配色，人物姿态自然，设备与人物关系易读。使用轻量背景形状组织构图，适合网页横幅，预留一侧文案空间，不添加文字与品牌标识。',true),
('illustration-watercolor','植物水彩插画','插画','绘制一幅柠檬枝植物水彩插画，包含成熟果实、叶片与少量花朵。以自然植物结构为基础，使用透明水彩叠色、柔和边缘和细微纸张肌理，保留明亮留白。果实色彩清新，叶片有自然差异，整体适合印刷装饰，不添加植物学标签、边框或水印。',true),
('space-living-room','客厅软装提案','空间','设计一间采光良好的现代小客厅：浅木色地板、米白沙发、低矮茶几与少量绿植，强调舒适的日常居住感。若提供房间照片，保留门窗、承重结构和主要空间比例，只调整软装。采用真实室内摄影视角，展示合理家具尺度与通行空间，不添加平面尺寸、虚构文字或不可能的结构。',true),
('space-cafe','咖啡店空间氛围','空间','为一家街角小咖啡店制作室内氛围提案，采用木色、暖白与少量墨绿，包含清楚的点单吧台、双人座位和靠窗长凳。午后自然光与柔和灯光共同照明，材料质感真实，座椅与通道尺度合理。画面表达空间气质，不添加虚构品牌、招牌文字或尺寸标注。',true),
('space-exhibition','展陈空间概念','空间','设计一处以海洋保护为主题的小型展览空间，使用蓝白配色、弧形展墙与克制的灯光。明确入口、主展项和参观动线，展品与观众保持可信尺度，主体展项突出，周边留有行走空间。输出真实感空间概念图，不生成难以辨认的展板文字、建筑尺寸或结构施工细节。',true),
('design-logo','品牌标志概念','视觉设计','为一家名为“山间”的独立咖啡店设计标志概念，以山形与咖啡杯轮廓的简洁组合为核心。采用单色深绿、少量笔画与均衡的负形，白色背景，图形边缘清楚，缩小后仍有辨识度。只展示图形标志，不生成文字、样机、阴影或复杂渐变。以清晰的平面图呈现，方便后续整理为矢量稿。',true),
('design-packaging','包装视觉概念','视觉设计','设计一款柚子气泡水的易拉罐包装视觉概念，以淡黄色、深绿和清新的柚子插画构成统一系统。展示一只正立罐体与清楚的正面设计，主次层级简洁，材质与印刷效果自然。若提供包装参考，保持原有罐型和必须保留的标识。不虚构配料、营养数据、认证和健康功效，未提供的文案区域留白。',true),
('design-pattern','重复纹样底稿','视觉设计','设计一张以橄榄枝与小花为元素的装饰纹样底稿，采用米白底色、低饱和绿与少量暖黄。元素疏密均衡、朝向自然变化，线条与色块风格统一，适合布料或包装的视觉探索。不添加文字、边框与立体阴影。按四边可衔接的方向组织构图，让纹样自然跨越画布边缘。',true),
('design-sticker','可爱贴纸套组','视觉设计','在干净浅色背景上绘制一组九枚咖啡主题贴纸，包含咖啡杯、咖啡壶、豆袋、可颂等不同物件。采用一致的圆润线条、暖色配色与白色切边轮廓，每枚贴纸独立完整、相互分隔，大小协调。使用整齐的三行布局，不重叠、不截断，不添加文字、水印或虚构品牌。',true),
('ui-dashboard','数据看板界面概念','界面','设计一张桌面端项目数据看板的界面概念图，包含简洁侧边导航、顶部工具栏、四个关键指标和两张趋势图。使用白底、浅灰分区与工程蓝强调色，统一间距、圆角和字体层级，信息按重要性组织，控件位置合理。图表使用合成示意数据，不使用真实个人信息。只表达界面视觉方向，不添加冗长说明和装饰性大图。',true),
('ui-landing-page','产品落地页概念','界面','设计一个面向小型团队的协作文档产品落地页首屏，采用简洁桌面网页布局：左侧标题与短文案区、明确主按钮，右侧展示文档协作界面缩略图。使用白色、淡蓝与深灰，留白充足，导航轻量，突出产品用途。文案使用简短示意内容，不虚构客户背书、用户数量或认证标识。',true),
('ui-icon-set','统一线性图标','界面','在白色背景上设计一组六枚统一线性图标，分别表达项目文件夹、图片、收藏、搜索、设置和下载。使用相同视觉尺寸、描边粗细、圆角与工程蓝颜色，轮廓清晰，细节适合小尺寸显示。各图标独立，按两行三列对齐排列，不添加文字、背景卡片、渐变或阴影。',true),
('portrait-professional','自然职业头像','人物','创作一张成年设计师的自然职业头像，半身构图，穿着简洁日常商务服装，神情放松、自信。使用浅灰背景、柔和窗光与自然肤色，保留真实皮肤纹理，避免过度磨皮和夸张美颜。如提供有权使用的人像参考，保持人物可辨识特征，不擅自改变年龄或添加身份标记，不出现文字与水印。',true),
('portrait-editorial','杂志感环境人像','人物','拍摄一位成年手艺人在明亮工作室整理陶器的环境人像。人物、手部动作与工作台关系自然，周围陈列少量工具与半成品，使用柔和侧光和克制的暖色调，保留真实皮肤、衣物及陶土质感。主体突出，背景传达职业氛围，避免多余手指、重复工具、夸张姿态和虚构文字。',true),
('portrait-character-sheet','原创角色设定','人物','为一名成年城市探险者制作原创角色设定图，短外套、轻便背包和实用鞋履，整体风格简洁易辨。横向排列正面、侧面和背面三个全身视图，保持发型、衣物结构、配色和身体比例一致，背景干净，姿态自然。不要借用现有影视或游戏角色，不添加武器、设定文字或水印。',true),
('creative-double-exposure','自然双重曝光','创意合成','创作一幅自然主题的双重曝光艺术图：成年人物的侧面轮廓与清晨森林融合，树木纹理在轮廓内部形成清楚层次，边缘自然过渡。采用深绿与暖金色，主体轮廓完整，亮暗有节奏，保留大面积干净背景。避免堆叠不相关元素、破碎五官、文字与水印。',true),
('creative-miniature','桌面微缩世界','创意合成','构建一个位于打开的旅行箱中的微缩海边小镇，包含白色小屋、弯曲街道、灯塔与一小片海湾。采用可信的模型材质、统一光源和俯斜摄影视角，尺度差异形成趣味，细节丰富但主次清楚。旅行箱与小镇接触合理，不添加文字、品牌或杂乱漂浮物。',true),
('creative-clay','黏土风格场景','创意合成','制作一幅手工黏土质感的早餐场景：圆润的面包、煎蛋、番茄和咖啡杯摆在小餐盘旁。使用柔和暖色、轻微手工压痕和均匀的工作室灯光，物件比例协调，整体可爱但有清楚的材质区分。背景简洁，不添加拟人五官、文字或水印。',true),
('diagram-process','三步流程图解','图解','为“播种、发芽、长成幼苗”制作横向三步图解，使用统一的简洁插画风格、自然绿配色和干净浅色背景。三个阶段从左到右等距排列，用清楚的箭头连接，土壤、种子与叶片的变化一目了然。每一步下方预留短标签位置，先不生成文字；不添加无关装饰。',true),
('diagram-exploded','产品结构示意','图解','制作一个普通保温杯的结构示意图，将杯盖、密封圈、内胆与外壳沿同一竖直轴有序分开，采用简洁的工业产品渲染风格。保持零件比例与装配关系易于理解，浅灰背景，柔和光照，右侧预留标注空间。仅作概念展示，不虚构精密尺寸、专利结构、性能数据或制造要求，不自动添加文字。',true),
('diagram-comparison','前后对比视觉','图解','设计一张桌面收纳前后对比图，左右使用同一房间、相同视角和光照。左侧表现物品随意堆放，右侧通过收纳盒、线缆整理与合理分区使桌面有序；桌椅、门窗和主要设备保持一致。对比明确但不过度夸张，上方预留简短标题区，不生成文字或虚构效果数据。',true)
